    derive: (i, deep) => {
      const p = (deep && deep.params) || {};
      const growth = p.growth || 1, k = p.peak || 3;
      const qDay = i.users * 1e6 * i.perUser * growth, q = qDay / 86400, peakQ = q * k;
      const nChunks = i.docs * 1e6 * i.chunks * growth, promptTok = SYS_TOK + 5 * CHUNK_TOK, units = i.outTok + promptTok / 10;
      return { growth, k, qDay, q, peakQ, nChunks, indexGB: (nChunks * VEC_KB) / 1e6, outTok: i.outTok, promptTok, units,
        docRate: (i.docs * 1e6 * growth * i.change) / 100 / 86400, chunkRate: (nChunks * i.change) / 100 / 86400,
        gpus: Math.ceil((peakQ * units) / GPU_TOK / 0.7) };
    },

